"""Database models for Flasky.

For convenience this module re-exports :func:`app.create_app`, :data:`app.db`
and the :mod:`app.fake` helper module, so that everything the project offers
can be pulled in with a single import::

    from app.models import (User, Role, Post, Comment, create_app, db, fake,
                            AnonymousUser, Permission, Follow)
"""

import hashlib
from datetime import datetime

import bleach
from flask import current_app, request, url_for
from flask_login import UserMixin, AnonymousUserMixin
from itsdangerous import TimedJSONWebSignatureSerializer as Serializer
from markdown import markdown
from werkzeug.security import generate_password_hash, check_password_hash

from . import db, login_manager, create_app  # noqa: F401
from .exceptions import ValidationError


def _url_for(endpoint, **values):
    """:func:`flask.url_for` that also works inside a bare app context.

    ``to_json()`` is frequently called from a plain ``app.app_context()`` (for
    instance from a shell or a unit test).  Werkzeug cannot build a URL adapter
    without either a request or ``SERVER_NAME``, so fall back on a throw-away
    test request context in that case.
    """
    try:
        return url_for(endpoint, **values)
    except RuntimeError:
        with current_app.test_request_context('/'):
            return url_for(endpoint, **values)


class Permission:
    """Bit flags for the individual permissions a role can grant."""

    FOLLOW = 1
    COMMENT = 2
    WRITE = 4
    MODERATE = 8
    ADMIN = 16


class Role(db.Model):
    __tablename__ = 'roles'
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(64), unique=True)
    default = db.Column(db.Boolean, default=False, index=True)
    permissions = db.Column(db.Integer)
    users = db.relationship('User', backref='role', lazy='dynamic')

    def __init__(self, **kwargs):
        super(Role, self).__init__(**kwargs)
        if self.permissions is None:
            self.permissions = 0

    @staticmethod
    def insert_roles():
        """Create (or update) the three roles used by the application.

        - ``User``: can follow, comment and write articles (the default role).
        - ``Moderator``: as ``User`` plus comment moderation.
        - ``Administrator``: as ``Moderator`` plus full administration rights.
        """
        roles = {
            'User': [Permission.FOLLOW, Permission.COMMENT, Permission.WRITE],
            'Moderator': [Permission.FOLLOW, Permission.COMMENT,
                          Permission.WRITE, Permission.MODERATE],
            'Administrator': [Permission.FOLLOW, Permission.COMMENT,
                              Permission.WRITE, Permission.MODERATE,
                              Permission.ADMIN],
        }
        default_role = 'User'
        for r in roles:
            role = Role.query.filter_by(name=r).first()
            if role is None:
                role = Role(name=r)
            role.reset_permissions()
            for perm in roles[r]:
                role.add_permission(perm)
            role.default = (role.name == default_role)
            db.session.add(role)
        db.session.commit()

    def add_permission(self, perm):
        """Grant ``perm`` to this role."""
        if not self.has_permission(perm):
            self.permissions += perm

    def remove_permission(self, perm):
        """Revoke ``perm`` from this role."""
        if self.has_permission(perm):
            self.permissions -= perm

    def reset_permissions(self):
        """Revoke every permission from this role."""
        self.permissions = 0

    def has_permission(self, perm):
        """Return ``True`` when this role grants ``perm``."""
        if self.permissions is None:
            return False
        return self.permissions & perm == perm

    def __repr__(self):
        return '<Role %r>' % self.name


class Follow(db.Model):
    __tablename__ = 'follows'
    follower_id = db.Column(db.Integer, db.ForeignKey('users.id'),
                            primary_key=True)
    followed_id = db.Column(db.Integer, db.ForeignKey('users.id'),
                            primary_key=True)
    timestamp = db.Column(db.DateTime, default=datetime.utcnow)

    def __repr__(self):
        return '<Follow %r -> %r>' % (self.follower_id, self.followed_id)


class User(UserMixin, db.Model):
    __tablename__ = 'users'
    id = db.Column(db.Integer, primary_key=True)
    email = db.Column(db.String(64), unique=True, index=True)
    username = db.Column(db.String(64), unique=True, index=True)
    role_id = db.Column(db.Integer, db.ForeignKey('roles.id'))
    password_hash = db.Column(db.String(128))
    confirmed = db.Column(db.Boolean, default=False)
    name = db.Column(db.String(64))
    location = db.Column(db.String(64))
    about_me = db.Column(db.Text())
    member_since = db.Column(db.DateTime(), default=datetime.utcnow)
    last_seen = db.Column(db.DateTime(), default=datetime.utcnow)
    avatar_hash = db.Column(db.String(32))
    posts = db.relationship('Post', backref='author', lazy='dynamic')
    followed = db.relationship('Follow',
                               foreign_keys=[Follow.follower_id],
                               backref=db.backref('follower', lazy='joined'),
                               lazy='dynamic',
                               cascade='all, delete-orphan')
    followers = db.relationship('Follow',
                                foreign_keys=[Follow.followed_id],
                                backref=db.backref('followed', lazy='joined'),
                                lazy='dynamic',
                                cascade='all, delete-orphan')
    comments = db.relationship('Comment', backref='author', lazy='dynamic')

    @staticmethod
    def add_self_follows():
        """Make every existing user follow themselves.

        Self-follows keep a user's own posts inside their followed-posts feed,
        which lets that feed be produced with a single join.
        """
        for user in User.query.all():
            if not user.is_following(user):
                user.follow(user)
                db.session.add(user)
                db.session.commit()

    def __init__(self, **kwargs):
        super(User, self).__init__(**kwargs)
        if self.role is None:
            if self.email is not None and \
                    self.email == current_app.config['FLASKY_ADMIN']:
                self.role = Role.query.filter_by(name='Administrator').first()
            if self.role is None:
                self.role = Role.query.filter_by(default=True).first()
        if self.email is not None and self.avatar_hash is None:
            self.avatar_hash = self.gravatar_hash()
        self.follow(self)

    @property
    def password(self):
        raise AttributeError('password is not a readable attribute')

    @password.setter
    def password(self, password):
        self.password_hash = generate_password_hash(password)

    def set_password(self, password):
        """Alias for the :attr:`password` setter."""
        self.password = password

    def verify_password(self, password):
        """Return ``True`` when ``password`` matches the stored hash."""
        if self.password_hash is None:
            return False
        return check_password_hash(self.password_hash, password)

    # Alias kept for symmetry with :meth:`set_password`.
    check_password = verify_password

    def generate_confirmation_token(self, expiration=3600):
        """Return a signed token that confirms this account."""
        s = Serializer(current_app.config['SECRET_KEY'], expiration)
        return s.dumps({'confirm': self.id}).decode('utf-8')

    def confirm(self, token):
        """Confirm this account from ``token``.

        :return: ``True`` when the token was valid and belongs to this user.
        """
        s = Serializer(current_app.config['SECRET_KEY'])
        try:
            data = s.loads(token.encode('utf-8'))
        except Exception:
            return False
        if data.get('confirm') != self.id:
            return False
        self.confirmed = True
        db.session.add(self)
        return True

    def generate_reset_token(self, expiration=3600):
        """Return a signed password-reset token for this user."""
        s = Serializer(current_app.config['SECRET_KEY'], expiration)
        return s.dumps({'reset': self.id}).decode('utf-8')

    @staticmethod
    def reset_password(token, new_password):
        """Reset the password of the user identified by ``token``.

        :return: ``True`` on success, ``False`` when the token is invalid or
            expired, or the user no longer exists.
        """
        s = Serializer(current_app.config['SECRET_KEY'])
        try:
            data = s.loads(token.encode('utf-8'))
        except Exception:
            return False
        user = User.query.get(data.get('reset'))
        if user is None:
            return False
        user.password = new_password
        db.session.add(user)
        return True

    def generate_email_change_token(self, new_email, expiration=3600):
        """Return a signed token that authorises a change to ``new_email``."""
        s = Serializer(current_app.config['SECRET_KEY'], expiration)
        return s.dumps({'change_email': self.id,
                        'new_email': new_email}).decode('utf-8')

    def change_email(self, token):
        """Apply the email change described by ``token``.

        :return: ``True`` when the email was changed, ``False`` otherwise.
        """
        s = Serializer(current_app.config['SECRET_KEY'])
        try:
            data = s.loads(token.encode('utf-8'))
        except Exception:
            return False
        if data.get('change_email') != self.id:
            return False
        new_email = data.get('new_email')
        if new_email is None:
            return False
        if User.query.filter_by(email=new_email).first() is not None:
            return False
        self.email = new_email
        self.avatar_hash = self.gravatar_hash()
        db.session.add(self)
        return True

    def can(self, perm):
        """Return ``True`` when this user's role grants ``perm``."""
        return self.role is not None and self.role.has_permission(perm)

    def is_administrator(self):
        """Return ``True`` when this user has administrative rights."""
        return self.can(Permission.ADMIN)

    def ping(self):
        """Record that the user was just seen."""
        self.last_seen = datetime.utcnow()
        db.session.add(self)

    def gravatar_hash(self):
        """Return the md5 hash of the user's email, used by Gravatar."""
        return hashlib.md5(self.email.lower().encode('utf-8')).hexdigest()

    def gravatar(self, size=100, default='identicon', rating='g'):
        """Return the URL of this user's Gravatar avatar image."""
        url = 'https://secure.gravatar.com/avatar'
        hash = self.avatar_hash or self.gravatar_hash()
        return '{url}/{hash}?s={size}&d={default}&r={rating}'.format(
            url=url, hash=hash, size=size, default=default, rating=rating)

    def follow(self, user):
        """Start following ``user`` (a no-op when already following)."""
        if not self.is_following(user):
            f = Follow(follower=self, followed=user)
            db.session.add(f)

    def unfollow(self, user):
        """Stop following ``user`` (a no-op when not following)."""
        f = self.followed.filter_by(followed_id=user.id).first()
        if f:
            db.session.delete(f)

    def is_following(self, user):
        """Return ``True`` when this user follows ``user``."""
        if user is None or user.id is None:
            return False
        return self.followed.filter_by(followed_id=user.id).first() is not None

    def is_followed_by(self, user):
        """Return ``True`` when ``user`` follows this user."""
        if user is None or user.id is None:
            return False
        return self.followers.filter_by(
            follower_id=user.id).first() is not None

    @property
    def followed_posts(self):
        """A query yielding every post written by someone this user follows."""
        return Post.query.join(Follow, Follow.followed_id == Post.author_id)\
            .filter(Follow.follower_id == self.id)

    def to_json(self):
        """Return a JSON-serialisable representation of this user."""
        json_user = {
            'url': _url_for('api.get_user', id=self.id),
            'username': self.username,
            'member_since': self.member_since,
            'last_seen': self.last_seen,
            'posts_url': _url_for('api.get_user_posts', id=self.id),
            'followed_posts_url': _url_for('api.get_user_followed_posts',
                                           id=self.id),
            'post_count': self.posts.count()
        }
        return json_user

    def generate_auth_token(self, expiration=3600):
        """Return a signed API authentication token for this user."""
        s = Serializer(current_app.config['SECRET_KEY'],
                       expires_in=expiration)
        return s.dumps({'id': self.id}).decode('utf-8')

    @staticmethod
    def verify_auth_token(token):
        """Return the :class:`User` encoded in ``token``, or ``None``."""
        s = Serializer(current_app.config['SECRET_KEY'])
        try:
            data = s.loads(token)
        except Exception:
            return None
        return User.query.get(data['id'])

    def __repr__(self):
        return '<User %r>' % self.username


class AnonymousUser(AnonymousUserMixin):
    """Stand-in for a visitor who is not logged in."""

    def can(self, permissions):
        return False

    def is_administrator(self):
        return False


login_manager.anonymous_user = AnonymousUser


@login_manager.user_loader
def load_user(user_id):
    return User.query.get(int(user_id))


class Post(db.Model):
    __tablename__ = 'posts'
    id = db.Column(db.Integer, primary_key=True)
    body = db.Column(db.Text)
    body_html = db.Column(db.Text)
    timestamp = db.Column(db.DateTime, index=True, default=datetime.utcnow)
    author_id = db.Column(db.Integer, db.ForeignKey('users.id'))
    comments = db.relationship('Comment', backref='post', lazy='dynamic')

    @staticmethod
    def on_changed_body(target, value, oldvalue, initiator):
        """Render ``body`` (Markdown) into sanitised HTML in ``body_html``."""
        allowed_tags = ['a', 'abbr', 'acronym', 'b', 'blockquote', 'code',
                        'em', 'i', 'li', 'ol', 'pre', 'strong', 'ul',
                        'h1', 'h2', 'h3', 'p']
        if value is None:
            target.body_html = None
            return
        target.body_html = bleach.linkify(bleach.clean(
            markdown(value, output_format='html'),
            tags=allowed_tags, strip=True))

    def to_json(self):
        """Return a JSON-serialisable representation of this post."""
        json_post = {
            'url': _url_for('api.get_post', id=self.id),
            'body': self.body,
            'body_html': self.body_html,
            'timestamp': self.timestamp,
            'author_url': _url_for('api.get_user', id=self.author_id),
            'comments_url': _url_for('api.get_post_comments', id=self.id),
            'comment_count': self.comments.count()
        }
        return json_post

    @staticmethod
    def from_json(json_post):
        """Build an unsaved :class:`Post` from a JSON dictionary.

        :raises ValidationError: when the ``body`` field is missing or empty.
        """
        body = (json_post or {}).get('body')
        if body is None or body == '':
            raise ValidationError('post does not have a body')
        return Post(body=body)

    def __repr__(self):
        return '<Post %r>' % self.id


db.event.listen(Post.body, 'set', Post.on_changed_body)


