from flask import g, jsonify
from flask_httpauth import HTTPBasicAuth

from . import api
from .errors import unauthorized, forbidden
from ..models import User

auth = HTTPBasicAuth()


@auth.verify_password
def verify_password(email_or_token, password):
    """Authenticate either an ``email``/``password`` pair or a token.

    A token is passed as the HTTP Basic *username* with an empty password.
    """
    if email_or_token == '':
        return False
    if password == '':
        g.current_user = User.verify_auth_token(email_or_token)
        g.token_used = True
        return g.current_user is not None
    user = User.query.filter_by(email=email_or_token.lower()).first()
    if not user:
        return False
    g.current_user = user
    g.token_used = False
    return user.verify_password(password)


@auth.error_handler
def auth_error():
    """Return the 401 response used for any failed authentication."""
    return unauthorized('Invalid credentials')


@api.before_request
@auth.login_required
def before_request():
    """Require an authenticated *and* confirmed account for every API call."""
    if not g.current_user.is_anonymous and \
            not g.current_user.confirmed:
        return forbidden('Unconfirmed account')


@api.route('/tokens/', methods=['POST'])
def get_token():
    """Issue a time limited API token for the authenticated user."""
    if g.current_user.is_anonymous or g.token_used:
        return unauthorized('Invalid credentials')
    return jsonify({'token': g.current_user.generate_auth_token(
        expiration=3600), 'expiration': 3600})
