from flask import jsonify

from . import api
from ..exceptions import ValidationError


def bad_request(message):
    """Return a 400 JSON response carrying ``message``."""
    response = jsonify({'error': 'bad request', 'message': message})
    response.status_code = 400
    return response


def unauthorized(message):
    """Return a 401 JSON response carrying ``message``."""
    response = jsonify({'error': 'unauthorized', 'message': message})
    response.status_code = 401
    return response


def forbidden(message):
    """Return a 403 JSON response carrying ``message``."""
    response = jsonify({'error': 'forbidden', 'message': message})
    response.status_code = 403
    return response


def not_found(message):
    """Return a 404 JSON response carrying ``message``."""
    response = jsonify({'error': 'not found', 'message': message})
    response.status_code = 404
    return response


@api.errorhandler(ValidationError)
def validation_error(e):
    """Translate a :class:`~app.exceptions.ValidationError` into a 400."""
    return bad_request(e.args[0])
